/* Service Worker — ReadLigero (strict offline-first)
 *
 * Install = two tiers (list + version come from precache-manifest.js, generated by tools/gen-precache.js):
 *   CORE      everything needed to start the app. Fetched all-or-nothing (with retries) so a half-cached app can never exist.
 *   OPTIONAL  pdf.js CMaps / standard fonts, xz decoder. Fetched best-effort after install, retried later (message FILL);
 *             a missing or slow optional file can NOT prevent offline mode.
 *
 * Redirect safety: many hosts (Netlify, Cloudflare Pages, Firebase…) redirect /index.html → /. A redirected response
 * must never be served to a navigation (the browser rejects it → offline start fails with ERR_FAILED), so every response
 * is stored as a clean copy and navigations are answered with the cached shell.
 *
 * A new version waits until the page asks for it (SKIP_WAITING), so a running session never mixes old and new files.
 */
importScripts('precache-manifest.js');

const CACHE_PREFIX = 'readligero-';
const CACHE_NAME = CACHE_PREFIX + self.PRECACHE_VERSION;
const ABS = (u) => new URL(u, self.location).href;
const SHELL_URLS = [ABS('./'), ABS('./index.html')];

/** Copy of a response that is safe to serve to any request (drops the "redirected" flag, keeps body + headers). */
async function clean(res) {
  if (!res.redirected && res.type !== 'opaqueredirect') return res;
  const body = await res.blob();
  return new Response(body, { status: res.status === 0 ? 200 : res.status, statusText: res.statusText, headers: res.headers });
}

/** Fetches one URL into the cache (3 attempts). Throws when it ultimately fails. */
async function store(cache, url) {
  let last;
  for (let i = 0; i < 3; i++) {
    try {
      const res = await fetch(new Request(url, { cache: 'reload', credentials: 'same-origin' }));
      if (!res.ok || res.status === 206) throw new Error(url + ' → HTTP ' + res.status);
      await cache.put(ABS(url), await clean(res));
      return;
    } catch (e) { last = e; await new Promise((r) => setTimeout(r, 300 * (i + 1))); }
  }
  throw last;
}

/** Runs `fn` over `items` with limited parallelism. Resolves to the list of failed items. */
async function pool(items, limit, fn) {
  const failed = []; let i = 0;
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (i < items.length) { const it = items[i++]; try { await fn(it); } catch (e) { failed.push(it); } }
  }));
  return failed;
}

async function missing(cache, urls) {
  const out = [];
  for (const u of urls) if (!(await cache.match(ABS(u)))) out.push(u);
  return out;
}

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    const todo = await missing(cache, self.PRECACHE_CORE);
    const failed = await pool(todo, 6, (u) => store(cache, u));
    if (failed.length) throw new Error('Precache failed for: ' + failed.slice(0, 5).join(', ') + (failed.length > 5 ? ' …' : ''));
    // optional tier: never fails the install
    event.waitUntil(pool(await missing(cache, self.PRECACHE_OPTIONAL), 4, (u) => store(cache, u)).catch(() => {}));
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith(CACHE_PREFIX) && k !== CACHE_NAME) await caches.delete(k);
    await self.clients.claim();
  })());
});

async function shell() {
  for (const u of SHELL_URLS) { const hit = await caches.match(u, { cacheName: CACHE_NAME }) || await caches.match(u); if (hit) return hit; }
  return null;
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  if (req.mode === 'navigate') {
    event.respondWith((async () => {
      const hit = await shell();
      if (hit) return hit;
      try { return await fetch(req); }
      catch (e) { return new Response('Offline, and the app is not cached yet. Open it once while online (over HTTPS).', { status: 503, headers: { 'Content-Type': 'text/plain' } }); }
    })());
    return;
  }

  event.respondWith((async () => {
    const hit = await caches.match(req, { cacheName: CACHE_NAME, ignoreSearch: true }) || await caches.match(req, { ignoreSearch: true });
    if (hit) return hit;
    try {
      const res = await fetch(req);
      if (res && res.ok && res.type === 'basic' && res.status === 200) {
        const copy = await clean(res.clone());
        caches.open(CACHE_NAME).then((c) => c.put(req, copy)).catch(() => {});
      }
      return res;
    } catch (e) { return new Response('', { status: 504, statusText: 'Offline' }); }
  })());
});

async function status() {
  const cache = await caches.open(CACHE_NAME);
  const all = self.PRECACHE_CORE.concat(self.PRECACHE_OPTIONAL);
  const miss = await missing(cache, all);
  const missCore = miss.filter((u) => self.PRECACHE_CORE.indexOf(u) > -1);
  return { type: 'STATUS', version: self.PRECACHE_VERSION, total: all.length, cached: all.length - miss.length, coreMissing: missCore.length, ready: missCore.length === 0 };
}

self.addEventListener('message', (event) => {
  const d = event.data || {}, port = event.ports && event.ports[0];
  const reply = (m) => { if (port) port.postMessage(m); else if (event.source) event.source.postMessage(m); };
  if (d.type === 'SKIP_WAITING') self.skipWaiting();
  else if (d.type === 'STATUS') event.waitUntil(status().then(reply));
  else if (d.type === 'FILL') {           // retry everything that is still missing, then report
    event.waitUntil((async () => {
      const cache = await caches.open(CACHE_NAME);
      await pool(await missing(cache, self.PRECACHE_CORE.concat(self.PRECACHE_OPTIONAL)), 4, (u) => store(cache, u));
      reply(await status());
    })());
  }
});
